	Map<String, Long> explicitIndexEntryCounts() throws IOException {
		return readTransaction(env, (stack, txn) -> {
			Map<String, Long> counts = new HashMap<>(indexes.size());
			MDBStat stat = MDBStat.malloc(stack);
			for (TripleIndex index : indexes) {
				E(mdb_stat(txn, index.getDB(true), stat));
				counts.put(index.toString(), stat.ms_entries());
			}
			return counts;
		});
	}

	long appendBulkIndex(String specification, BulkIndexTupleSource source, int maxTransactionRecords,
			long maxTransactionBytes) throws IOException {
		Objects.requireNonNull(source, "source");
		int batchRecords = bulkBatchRecords(maxTransactionRecords, maxTransactionBytes, 128L);
		TripleIndex index = indexes.stream()
				.filter(candidate -> candidate.toString().equals(specification))
				.findFirst()
				.orElseThrow(() -> new IOException("Statement index is not configured: " + specification));
		if (!TripleIndex.usesUnsignedTupleOrder(specification)) {
			throw new IOException("Statement index requires encoded-key sorting: " + specification);
		}
		if (!bulkAppendedExplicitIndexes.add(specification)) {
			throw new IOException("Statement index was already appended by this bulk load: " + specification);
		}

		long[] batch = new long[Math.multiplyExact(batchRecords, 4)];
		long[] tuple = new long[4];
		long[] previousTuple = new long[4];
		boolean hasPreviousTuple = false;
		boolean exhausted = false;
		long uniqueStatements = 0L;
		byte[] lastCommittedKey = null;
		while (!exhausted) {
			int count = 0;
			while (count < batchRecords) {
				if (!source.next(tuple)) {
					exhausted = true;
					break;
				}
				if (hasPreviousTuple) {
					int comparison = compareUnsignedTuple(previousTuple, tuple);
					if (comparison > 0) {
						throw new IOException("Statement index input is not sorted for " + specification);
					}
					if (comparison == 0) {
						continue;
					}
				}
				System.arraycopy(tuple, 0, previousTuple, 0, tuple.length);
				hasPreviousTuple = true;
				System.arraycopy(tuple, 0, batch, count * 4, tuple.length);
				count++;
			}
			if (count == 0) {
				continue;
			}
			lastCommittedKey = appendBulkIndexBatch(index, specification, batch, count, lastCommittedKey);
			uniqueStatements += count;
		}
		return uniqueStatements;
	}

	long appendBulkEncodedIndex(String specification, ValueStore.BulkRecordSource source, int maxTransactionRecords,
			long maxTransactionBytes) throws IOException {
		Objects.requireNonNull(source, "source");
		int batchRecords = bulkBatchRecords(maxTransactionRecords, maxTransactionBytes, 128L);
		TripleIndex index = indexes.stream()
				.filter(candidate -> candidate.toString().equals(specification))
				.findFirst()
				.orElseThrow(() -> new IOException("Statement index is not configured: " + specification));
		if (!bulkAppendedExplicitIndexes.add(specification)) {
			throw new IOException("Statement index was already appended by this bulk load: " + specification);
		}

		long[] batch = new long[Math.multiplyExact(batchRecords, 4)];
		byte[] previousInputKey = null;
		long[] previousQuad = new long[4];
		boolean exhausted = false;
		long uniqueStatements = 0L;
		byte[] lastCommittedKey = null;
		while (!exhausted) {
			int count = 0;
			while (count < batchRecords) {
				ValueStore.BulkRecord record = source.next();
				if (record == null) {
					exhausted = true;
					break;
				}
				long[] quad = decodeEncodedIndexRecord(specification, record);
				if (previousInputKey != null) {
					int comparison = Arrays.compareUnsigned(previousInputKey, record.key());
					if (comparison > 0) {
						throw new IOException("Encoded statement index input is not sorted for " + specification);
					}
					if (comparison == 0) {
						if (!Arrays.equals(previousQuad, quad)) {
							throw new IOException("Encoded statement index key collision for " + specification);
						}
						continue;
					}
				}
				previousInputKey = record.key();
				System.arraycopy(quad, 0, previousQuad, 0, quad.length);
				int offset = count * 4;
				for (int field = 0; field < 4; field++) {
					batch[offset + field] = quad[indexComponent(specification.charAt(field))];
				}
				count++;
			}
			if (count == 0) {
				continue;
			}
			lastCommittedKey = appendBulkIndexBatch(index, specification, batch, count, lastCommittedKey);
			uniqueStatements += count;
		}
		return uniqueStatements;
	}

	void appendBulkContexts(BulkContextSource source, int maxTransactionRecords, long maxTransactionBytes)
			throws IOException {
		Objects.requireNonNull(source, "source");
		if (bulkContextsAppended) {
			throw new IOException("Contexts were already appended by this bulk load");
		}
		bulkContextsAppended = true;
		int batchRecords = bulkBatchRecords(maxTransactionRecords, maxTransactionBytes, 64L);
		long[] batch = new long[Math.multiplyExact(batchRecords, 2)];
		long[] contextAndCount = new long[2];
		long previousContext = 0L;
		boolean hasPrevious = false;
		boolean exhausted = false;
		while (!exhausted) {
			int count = 0;
			while (count < batchRecords) {
				if (!source.next(contextAndCount)) {
					exhausted = true;
					break;
				}
				if (contextAndCount[1] <= 0L) {
					throw new IOException("Bulk context count must be positive");
				}
				if (hasPrevious && Long.compareUnsigned(previousContext, contextAndCount[0]) >= 0) {
					throw new IOException("Bulk contexts are not strictly increasing");
				}
				previousContext = contextAndCount[0];
				hasPrevious = true;
				batch[count * 2] = contextAndCount[0];
				batch[count * 2 + 1] = contextAndCount[1];
				count++;
			}
			if (count > 0) {
				appendBulkContextBatch(batch, count);
			}
		}
	}

	private static int bulkBatchRecords(int maxTransactionRecords, long maxTransactionBytes,
			long conservativeBytesPerRecord) {
		if (maxTransactionRecords <= 0 || maxTransactionBytes <= 0L) {
			throw new IllegalArgumentException("Bulk transaction record and byte limits must be positive");
		}
		long recordsByBytes = Math.max(1L, maxTransactionBytes / conservativeBytesPerRecord);
		return Math.toIntExact(Math.min(maxTransactionRecords, recordsByBytes));
	}

	private static long[] decodeEncodedIndexRecord(String specification, ValueStore.BulkRecord record)
			throws IOException {
		if (record.value().length != 4 * Long.BYTES) {
			throw new IOException("Encoded statement index value must contain four longs for " + specification);
		}
		ByteBuffer value = ByteBuffer.wrap(record.value());
		long[] quad = { value.getLong(), value.getLong(), value.getLong(), value.getLong() };
		byte[] expectedKey = TripleIndex.encodeKey(specification, quad[0], quad[1], quad[2], quad[3]);
		if (!Arrays.equals(expectedKey, record.key())) {
			throw new IOException("Encoded statement index record does not match its canonical quad for "
					+ specification);
		}
		return quad;
	}

	private static int indexComponent(char field) {
		return switch (field) {
		case 's' -> 0;
		case 'p' -> 1;
		case 'o' -> 2;
		case 'c' -> 3;
		default -> throw new IllegalArgumentException("Unknown statement index field: " + field);
		};
	}

	private byte[] appendBulkIndexBatch(TripleIndex index, String specification, long[] batch, int count,
			byte[] lastCommittedKey) throws IOException {
		long reservation = Math.multiplyExact((long) count, 128L);
		while (true) {
			reserveWriteCapacity(reservation);
			startTransaction();
			unjournaledMutation = true;
			nativeMutation = true;
			tripleMutation = true;
			try {
				byte[] finalKey = appendBulkIndexBatchInTransaction(index, specification, batch, count,
						lastCommittedKey);
				endTransaction(true);
				return finalKey;
			} catch (MapFullException e) {
				endTransaction(false);
				if (!autoGrow) {
					throw e;
				}
				reservation = Math.multiplyExact(reservation, 2L);
			} catch (IOException e) {
				endTransaction(false);
				throw e;
			} catch (RuntimeException | Error e) {
				endTransaction(false);
				throw e;
			}
		}
	}

	private byte[] appendBulkIndexBatchInTransaction(TripleIndex index, String specification, long[] batch, int count,
			byte[] lastCommittedKey) throws IOException {
		int subjectPosition = specification.indexOf('s');
		int predicatePosition = specification.indexOf('p');
		int objectPosition = specification.indexOf('o');
		int contextPosition = specification.indexOf('c');
		byte[] previousKey = lastCommittedKey == null ? new byte[TripleIndex.MAX_KEY_LENGTH]
				: Arrays.copyOf(lastCommittedKey, TripleIndex.MAX_KEY_LENGTH);
		int previousKeyLength = lastCommittedKey == null ? 0 : lastCommittedKey.length;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal keyVal = MDBVal.malloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			ByteBuffer keyBuffer = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
			for (int row = 0; row < count; row++) {
				int offset = row * 4;
				long subject = batch[offset + subjectPosition];
				long predicate = batch[offset + predicatePosition];
				long object = batch[offset + objectPosition];
				long context = batch[offset + contextPosition];
				keyBuffer.clear();
				index.toKey(keyBuffer, subject, predicate, object, context);
				keyBuffer.flip();
				if (previousKeyLength > 0 && compareUnsignedKey(previousKey, previousKeyLength, keyBuffer) >= 0) {
					throw new IOException("Unsigned tuple order does not match encoded LMDB key order for "
							+ specification);
				}
				LmdbUtil.setMDBValData(keyVal, keyBuffer);
				int rc = mdb_put(writeTxn, index.getDB(true), keyVal, dataVal, MDB_APPEND);
				if (rc == MDB_MAP_FULL) {
					throw new MapFullException();
				}
				if (rc != MDB_SUCCESS) {
					throw new IOException(mdb_strerror(rc));
				}
				previousKeyLength = keyBuffer.remaining();
				for (int i = 0; i < previousKeyLength; i++) {
					previousKey[i] = keyBuffer.get(keyBuffer.position() + i);
				}
			}
		}
		return Arrays.copyOf(previousKey, previousKeyLength);
	}

	private void appendBulkContextBatch(long[] batch, int count) throws IOException {
		long reservation = Math.multiplyExact((long) count, 64L);
		while (true) {
			reserveWriteCapacity(reservation);
			startTransaction();
			unjournaledMutation = true;
			nativeMutation = true;
			tripleMutation = true;
			try (MemoryStack stack = stackPush()) {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack);
				ByteBuffer keyBuffer = stack.malloc(1 + Long.BYTES);
				ByteBuffer valueBuffer = stack.malloc(1 + Long.BYTES);
				for (int row = 0; row < count; row++) {
					keyBuffer.clear();
					Varint.writeUnsigned(keyBuffer, batch[row * 2]);
					key.mv_data(keyBuffer.flip());
					valueBuffer.clear();
					Varint.writeUnsigned(valueBuffer, batch[row * 2 + 1]);
					value.mv_data(valueBuffer.flip());
					int result = mdb_put(writeTxn, contextsDbi, key, value, MDB_APPEND);
					if (result == MDB_MAP_FULL) {
						throw new MapFullException();
					}
					if (result != MDB_SUCCESS) {
						throw new IOException(mdb_strerror(result));
					}
				}
				endTransaction(true);
				return;
			} catch (MapFullException e) {
				endTransaction(false);
				if (!autoGrow) {
					throw e;
				}
				reservation = Math.multiplyExact(reservation, 2L);
			} catch (IOException e) {
				endTransaction(false);
				throw e;
			} catch (RuntimeException | Error e) {
				endTransaction(false);
				throw e;
			}
		}
	}

	private static int compareUnsignedTuple(long[] left, long[] right) {
		for (int component = 0; component < 4; component++) {
			int comparison = Long.compareUnsigned(left[component], right[component]);
			if (comparison != 0) {
				return comparison;
			}
		}
		return 0;
	}

	private static int compareUnsignedKey(byte[] left, int leftLength, ByteBuffer right) {
		int length = Math.min(leftLength, right.remaining());
		for (int i = 0; i < length; i++) {
			int comparison = Integer.compare(Byte.toUnsignedInt(left[i]),
					Byte.toUnsignedInt(right.get(right.position() + i)));
			if (comparison != 0) {
				return comparison;
			}
		}
		return Integer.compare(leftLength, right.remaining());
	}

	long lastTransactionId() throws IOException {
		try (MemoryStack stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(env, info));
			return info.me_last_txnid();
		}
	}

	void beginBulkOwnership() throws IOException {
		if (expectedNativeTransactionId >= 0L) {
			trustedTransactionId();
		} else {
			expectedNativeTransactionId = lastTransactionId();
		}
	}

	long validatedBulkTransactionId() throws IOException {
		return trustedTransactionId();
	}

	long trustedTransactionId() throws IOException {
		long current = lastTransactionId();
		if (nativeOwnershipInvalidated || expectedNativeTransactionId < 0L || current != expectedNativeTransactionId) {
			nativeOwnershipInvalidated = true;
			throw new IOException("TripleStore observed an unowned native transaction");
		}
		return current;
	}

	long trustedClosedTransactionId() {
		return nativeOwnershipInvalidated ? -1L : expectedNativeTransactionId;
	}

	boolean tracksNativeOwnership() {
		return expectedNativeTransactionId >= 0L;
	}

	void completeValidatedBulkGeneration(byte[] generation, long expectedStatements) throws IOException {
		if (expectedNativeTransactionId < 0L || lastTransactionId() != expectedNativeTransactionId) {
			throw new IOException("Bulk triple generation has an unrecognized native writer");
		}
		for (long entries : explicitIndexEntryCounts().values()) {
			if (entries != expectedStatements) {
				throw new IOException("Incomplete bulk statement index");
			}
		}
		reserveWriteCapacity(PreparedBulkStore.GENERATION_KEY.length + generation.length);
		startTransaction();
		try (MemoryStack stack = stackPush()) {
			writeNamespaceDatabaseValue(stack, writeTxn, PreparedBulkStore.GENERATION_KEY, generation);
			nativeMutation = true;
			unjournaledMutation = true;
			endTransaction(true);
		} catch (IOException | RuntimeException | Error failure) {
			endTransaction(false);
			throw failure;
		}
		E(mdb_env_sync(env, true));
	}

	/**
	 * Explicit final planning under the private bulk owner's exclusive lifecycle. The next metadata commit persists it.
	 */
	void reserveBulkCompletionCapacity(long additionalStatements, long minimumBytes) throws IOException {
		trustedTransactionId();
		if (writeTxn != 0L || additionalStatements < 0L) {
			throw new IOException("Cannot plan capacity for an active bulk triple generation");
		}
		long reservation = estimateWriteBytes(additionalStatements);
		if (additionalStatements > 0L) {
			long copiedTreeBytes = LmdbUtil.readTransaction(env, (stack, txn) -> {
				MDBStat stat = MDBStat.malloc(stack);
				long treePages = 0L;
				for (TripleIndex index : indexes) {
					E(mdb_stat(txn, index.getDB(true), stat));
					treePages = Math.addExact(treePages,
							Math.addExact(stat.ms_branch_pages(), Math.multiplyExact(stat.ms_leaf_pages(), 2L)));
				}
				return Math.multiplyExact(treePages, pageSize);
			});
			reservation = Math.addExact(reservation, copiedTreeBytes);
		}
		reservation = Math.addExact(reservation, LmdbUtil.MIN_FREE_SPACE);
		long target = growthPolicy.minimumMapSize(Math.max(mapSize, Math.max(1L, minimumBytes)), pageSize,
				Math.addExact(occupiedBytes(), reservation));
		if (target <= mapSize) {
			return;
		}
		var manager = txnManager.lockManager();
		long stamp;
		try {
			stamp = manager.writeLock();
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while reserving bulk triple capacity", interrupted);
		}
		try {
			txnManager.deactivate();
			try {
				E(setMapSize(target));
				mapSize = target;
				bulkMapGrowthCount++;
			} finally {
				txnManager.activate();
			}
		} finally {
			manager.unlockWrite(stamp);
		}
	}

