	int secondaryIndexCount() {
		return Math.max(0, indexes.size() - 1);
	}

	boolean supportsGlobalPreparedOrder() {
		return hasFourIndexPreparedOrder();
	}

	static int openPreparedKeyArenaCount() {
		return OPEN_PREPARED_KEY_ARENAS.get();
	}

